window.CWArcade=(game,action,data={})=>new Promise((resolve,reject)=>{const key=crypto.randomUUID(),timer=setTimeout(()=>{pending.delete(key);reject(Error('Connection timed out. Refresh to recover your bet.'));},15000);pending.set(key,{resolve,reject,timer});parent.postMessage({type:'cw-arcade-request',game,action,data,key},'*');});const pending=new Map();window.addEventListener('message',e=>{if(e.source!==parent||e.data?.type!=='cw-arcade-response')return;const p=pending.get(e.data.key);if(!p)return;pending.delete(e.data.key);clearTimeout(p.timer);e.data.error?p.reject(Error(e.data.error)):p.resolve(e.data.result);});